select case when customers.credit_limit >= 15700 then 'high' when customers.credit_limit >= 4800 then 'mid' else 'low' end as credit_limit_bucket, max(sessions.started_at) as last_started_at, max(sessions.started_at) as latest_started_at from sessions join customers on sessions.customer_id = customers.id where length(customers.name) < 11 group by case when customers.credit_limit >= 15700 then 'high' when customers.credit_limit >= 4800 then 'mid' else 'low' end order by latest_started_at desc, credit_limit_bucket
